import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.DiAOIirN.js";var i=JSON.parse(`{"title":"Configuration","description":"","frontmatter":{},"headers":[],"relativePath":"guide/configuration.md","filePath":"guide/configuration.md","lastUpdated":1788465684000}`),a={name:`guide/configuration.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to “Configuration”">​</a></h1><p>Everything is an environment variable. The full table with types and defaults is in the <a href="/reference/environment">environment reference</a>; this page explains the ones with consequences.</p><h2 id="connecting" tabindex="-1">Connecting <a class="header-anchor" href="#connecting" aria-label="Permalink to “Connecting”">​</a></h2><p><code>SMTP_HOST</code>, <code>SMTP_USER</code> and <code>SMTP_PASSWORD</code> are the account. <code>SMTP_PORT</code> follows <code>SMTP_TLS</code> unless you set it.</p><table tabindex="0"><thead><tr><th><code>SMTP_TLS</code></th><th>Default port</th><th>Behaviour</th></tr></thead><tbody><tr><td><code>starttls</code></td><td>587</td><td>Connects in the clear and <strong>requires</strong> the upgrade. The default.</td></tr><tr><td><code>implicit</code></td><td>465</td><td>TLS from the first byte.</td></tr><tr><td><code>none</code></td><td>25</td><td>No encryption, ever.</td></tr></tbody></table><p><code>starttls</code> requires the upgrade rather than attempting it. That distinction is the whole point: left to a library default, STARTTLS is used when the server offers it and skipped when it does not — so an attacker who can strip the capability from the server&#39;s greeting gets a cleartext session carrying your password, and nothing says a word. Here that is a failed connection.</p><p><code>none</code> means none, not &quot;encrypt if it happens to be offered&quot;. A mode whose behaviour depends on what the peer advertises is a mode nobody can reason about. Against a non-loopback host it prints a warning.</p><p><code>SMTP_INSECURE_TLS=true</code> accepts self-signed certificates. It is scoped to this server&#39;s own connection and never touches process-wide TLS verification — but prefer a proper internal CA.</p><h2 id="the-sender" tabindex="-1">The sender <a class="header-anchor" href="#the-sender" aria-label="Permalink to “The sender”">​</a></h2><p><code>SMTP_FROM</code> is the only sender this server will use, in either form:</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_FROM</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&#39;person@example.net&#39;</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_FROM</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&#39;Your Name &lt;person@example.net&gt;&#39;</span></span></code></pre></div><p>There is no <code>from</code> tool parameter, and adding one is out of scope. A model that can choose its own sender can write in a colleague&#39;s name, and the message that results is indistinguishable from one they wrote. The envelope sender is the bare address out of this value, so SPF and DKIM line up with what the recipient sees.</p><h2 id="turning-sending-on" tabindex="-1">Turning sending on <a class="header-anchor" href="#turning-sending-on" aria-label="Permalink to “Turning sending on”">​</a></h2><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_ALLOW_SEND</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">true</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_ALLOWED_RECIPIENTS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&#39;@example.net,partner@example.org&#39;</span></span></code></pre></div><p><code>SMTP_ALLOW_SEND</code> accepts exactly the string <code>true</code>. Anything else — <code>TRUE</code>, <code>1</code>, <code>yes</code> — leaves sending off, because a variable that guards an outbound channel should not be permissive about what counts as consent.</p><p><code>SMTP_ALLOWED_RECIPIENTS</code> is <strong>required</strong> when sending is on. Entries are:</p><table tabindex="0"><thead><tr><th>Entry</th><th>Matches</th></tr></thead><tbody><tr><td><code>@example.net</code></td><td>any address at that domain, and <strong>not</strong> at a subdomain</td></tr><tr><td><code>person@example.net</code></td><td>exactly that address</td></tr><tr><td><code>*</code></td><td>anyone — must be the only entry</td></tr></tbody></table><p>A domain rule does not cover its subdomains. Subdomain matching is the kind of convenience that turns one allowlisted domain into whatever anyone can register underneath it; if you want <code>@mail.example.net</code>, name it.</p><p><code>*</code> cannot be combined with other entries. Together they read as &quot;these, plus a wildcard somebody forgot to remove&quot;, and the person deleting the real entries later believes they are tightening the list. They are not — <code>*</code> already allowed everything.</p><p>Malformed entries stop the server rather than matching nothing, and comparison is done on the bytes as written: a homoglyph domain simply fails to match, which is the direction this has to fail in.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to “Limits”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Default</th><th>What it bounds</th></tr></thead><tbody><tr><td><code>SMTP_MAX_RECIPIENTS</code></td><td><code>10</code></td><td>distinct addresses across To, Cc and Bcc in one message</td></tr><tr><td><code>SMTP_MAX_SENDS_PER_HOUR</code></td><td><code>20</code></td><td>messages in a sliding hour</td></tr><tr><td><code>SMTP_MAX_MESSAGE_BYTES</code></td><td><code>10485760</code></td><td>the composed message, after encoding</td></tr><tr><td><code>SMTP_MAX_ATTACHMENT_BYTES</code></td><td><code>5242880</code></td><td>one attachment, before encoding</td></tr></tbody></table><p>The hourly cap is held in memory and resets when the server restarts. That is a deliberate trade: a counter in a file would need locking, would drift when two clients run the server at once, and would turn a corrupt state file into a server that refuses to send at all. Read it as a blast-radius limit, not as a quota.</p><h2 id="attachments" tabindex="-1">Attachments <a class="header-anchor" href="#attachments" aria-label="Permalink to “Attachments”">​</a></h2><p>Attachments are unavailable until <code>SMTP_ATTACHMENT_DIR</code> names a directory. Callers then name a file <strong>inside</strong> it — a plain filename, no path — and everything else is refused: separators, <code>..</code>, leading dots, symlinks, extensions outside <code>SMTP_ATTACHMENT_TYPES</code>, executable extensions, and anything whose leading bytes say it is a binary regardless of what it is called.</p><p>The default type list is documents and images. Two things are deliberately not on it and have to be written into <code>SMTP_ATTACHMENT_TYPES</code> by hand: <code>text/html</code>, because an HTML <em>file</em> opens in a browser with none of a mail client&#39;s restrictions and none of the sanitising the HTML <em>part</em> of a message gets — the phishing shape called HTML smuggling — and <code>application/zip</code>, because an archive passes the magic-byte check on its own bytes and can carry an executable the check never sees.</p><p>The directory is the only source of the path. A caller cannot choose which part of your disk gets mailed out.</p><h2 id="signature-and-audit" tabindex="-1">Signature and audit <a class="header-anchor" href="#signature-and-audit" aria-label="Permalink to “Signature and audit”">​</a></h2><p><code>SMTP_SIGNATURE</code> is appended below the standard <code>-- </code> delimiter, which is what makes mail clients hide it when quoting a reply.</p><p><code>SMTP_AUDIT_LOG</code> names a file that receives a copy of every audit line. Those lines always go to stderr; the file is what makes the record outlive the terminal the client was started in. It holds the recipients, the subject, the Message-ID and the size — never the body.</p><p>Refused sends are written down too, marked <code>outcome=refused</code>, <code>declined</code> or <code>token_rejected</code>, with the recipients and the subject that were asked for. A session that is being steered mostly produces refusals — an address off the allowlist, a token that did not match — and those lines are what shows it was being steered.</p><h2 id="turning-the-approval-dialog-off" tabindex="-1">Turning the approval dialog off <a class="header-anchor" href="#turning-the-approval-dialog-off" aria-label="Permalink to “Turning the approval dialog off”">​</a></h2><p>Every send asks a person through MCP elicitation before the message leaves. <code>ELICITATION=false</code> takes it to the two-call token instead. It does not remove the guard; there is no setting in which a message goes out unannounced.</p><p>The variable deliberately carries no <code>SMTP_</code> prefix, which means it reaches every MCP server in the same environment — and this is the server where that costs the most. Unlike <code>SMTP_ALLOW_SEND</code>, a value it does not recognise <strong>stops the server</strong> rather than failing off. See <a href="/guide/approval">Asking a person</a>.</p><h2 id="choosing-the-tools-that-load" tabindex="-1">Choosing the tools that load <a class="header-anchor" href="#choosing-the-tools-that-load" aria-label="Permalink to “Choosing the tools that load”">​</a></h2><p><code>SMTP_ALLOW_TOOLS</code> decides what is registered; <code>SMTP_DENY_TOOLS</code> is subtracted from it. Both take comma-separated tool names, or a prefix with a single trailing <code>*</code>.</p><div class="language-sh"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light-default github-dark-default" style="--shiki-light:#1f2328;--shiki-dark:#e6edf3;--shiki-light-bg:#ffffff;--shiki-dark-bg:#0d1117;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">essential</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&#39;get_server_info,preview_mail&#39;</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_ALLOW_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">&#39;send_*&#39;</span></span>
<span class="line"><span style="--shiki-light:#1F2328;--shiki-dark:#E6EDF3;">SMTP_DENY_TOOLS</span><span style="--shiki-light:#CF222E;--shiki-dark:#FF7B72;">=</span><span style="--shiki-light:#0A3069;--shiki-dark:#A5D6FF;">forward_mail</span></span></code></pre></div><p><code>essential</code> selects a curated five: <code>get_server_info</code>, <code>validate_recipients</code>, <code>preview_mail</code>, <code>send_mail</code> and <code>reply_mail</code>. <code>forward_mail</code> is left out on purpose — forwarding carries somebody else&#39;s content and attachments outward, which is the call that most deserves to be switched on deliberately.</p><p>A filtered tool is not built. It does not appear in <code>tools/list</code> and a call answers &quot;not found&quot;, exactly like a sending tool while <code>SMTP_ALLOW_SEND</code> is unset. Nothing is advertised and then refused.</p><p>An entry matching no tool aborts startup and lists the real names. That is louder than it sounds and it is the point: a tool quietly missing from <code>tools/list</code> is invisible, and nobody traces an absence back to an environment variable. A pattern that matches only sending tools while sending is off is a warning rather than an error — a pattern is a template, not a claim about one tool — but an exact name in that position is fatal, because somebody typed it believing it was exposed.</p>`,40)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};